        val = (my_adv_sum - opp_adv_sum) + (my_best * -0.5) + (free_nb * 0.2) + (opp_best * -0.1)

        if best_val is None or val > best_val:
            best_val = val
            best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

